/** Seconds a caption stays on screen: enough to read it comfortably. */
export const captionSeconds = (text) => Math.max(6, Math.round((4 + text.length / 11) * 2) / 2);
export const sceneSeconds = (scene) => scene.captions.reduce((sum, text) => sum + captionSeconds(text), 0);
export const lessonSeconds = (lesson) => lesson.scenes.reduce((sum, scene) => sum + sceneSeconds(scene), 0);
